package it.frociart.app;
/** Length-prefixed UTF16 fields preserve unfinished form input, including invalid template syntax. */
final class FlowTemplateDraft {
    final String name,base,extension,instructions,body;final boolean caseSensitive;
    FlowTemplateDraft(String n,String l,String e,String i,String b,boolean s){name=n==null?"":n;base=l==null?"":l;extension=e==null?"":e;instructions=i==null?"":i;body=b==null?"":b;caseSensitive=s;}
    FlowTemplateDraft(FlowCodeTemplate definition){this(definition.name,definition.base,definition.extension,definition.instructions,definition.body,definition.caseSensitive);}
    FlowCodeTemplate definition(){return FlowCodeTemplate.create(name,base,extension,instructions,body,caseSensitive);}
    String encode(){String[] fields={name,base,extension,instructions,body,caseSensitive?"true":"false"};int[] limits={80,64,16,1000,262144,5};for(int i=0;i<fields.length;i++)if(fields[i].length()>limits[i])throw new IllegalArgumentException("La bozza del modello supera il limite.");StringBuilder b=new StringBuilder("FrociartTemplateDraft1\n");for(String field:new String[]{name,base,extension,instructions,body,caseSensitive?"true":"false"})b.append(field.length()).append('\n').append(field);String result=b.toString();if(result.length()>524288)throw new IllegalArgumentException("La bozza del modello supera il limite.");return result;}
    static FlowTemplateDraft decode(String text){String magic="FrociartTemplateDraft1\n";if(text==null||text.length()>524288||!text.startsWith(magic))throw new IllegalArgumentException("Formato della bozza del modello non valido.");int at=magic.length();String[] values=new String[6];int[] limits={80,64,16,1000,262144,5};for(int i=0;i<values.length;i++){int end=text.indexOf('\n',at),length;try{if(end<0||end-at>6||end==at||!text.substring(at,end).matches("[0-9]+"))throw new NumberFormatException();length=Integer.parseInt(text.substring(at,end));if(length>limits[i]||length>text.length()-end-1)throw new NumberFormatException();}catch(NumberFormatException ex){throw new IllegalArgumentException("La bozza del modello è incompleta o troppo lunga.");}at=end+1;values[i]=text.substring(at,at+length);at+=length;}if(at!=text.length()||!values[5].equals("true")&&!values[5].equals("false"))throw new IllegalArgumentException("La bozza del modello contiene dati non validi.");return new FlowTemplateDraft(values[0],values[1],values[2],values[3],values[4],values[5].equals("true"));}
}
